<?php require_once __DIR__.'/../../middleware/bootstrap.php';require_once __DIR__.'/../../config/database.php';$u=require_login();$s=$pdo->prepare('SELECT b.id,b.travel_date,b.travellers,b.total_amount,b.booking_status,b.created_at,p.package_name,d.destination_name FROM bookings b JOIN packages p ON p.id=b.package_id JOIN destinations d ON d.id=p.destination_id WHERE b.user_id=? ORDER BY b.created_at DESC');$s->execute([$u['id']]);json_out(['bookings'=>$s->fetchAll()]);
